<div class="page-heading"><div><div class="eyebrow">SCHOOL WORKSPACE</div><h1>Students<span class="green">.</span></h1><p>One student profile, with every class and payment together.</p></div><div class="actions"><a class="button" download href="<?= e(url('export/students')) ?>">Export CSV</a><button class="button primary" data-open="student-dialog">Add student</button></div></div>
<section class="panel"><form method="get" class="filters"><label class="search-field"><input name="q" aria-label="Search students" placeholder="Search name, phone, address, or account" value="<?= e($q) ?>"></label><select name="class" aria-label="Class" data-searchable><option value="">All classes</option><?php foreach($classes as $c): ?><option value="<?= $c['id'] ?>" <?= $classId==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select><select name="status" aria-label="Status"><option value="">All statuses</option><?php foreach(['Active','Inactive'] as $v): ?><option <?= $status===$v?'selected':'' ?>><?= $v ?></option><?php endforeach ?></select><button class="button">Apply filters</button><a class="text-link" href="<?= e(url('students')) ?>">Reset</a></form>
<div class="table-wrap"><table><thead><tr><th>Name</th><th>Phone</th><th>Address</th><th>Origin</th><th>Account</th><th>Classes</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($filtered as $s): ?><tr><td><a class="text-link student-detail-link" href="<?= e(url('students/'.$s['id'])) ?>" title="View student details"><?= e($s['name']) ?></a></td><td><?= e($s['phone']) ?></td><td><?= e($s['address']) ?></td><td><?= e($s['origin']) ?></td><td><?= e($s['account']?:'—') ?></td><td><?= e($s['class_name']) ?></td><td><span class="badge <?= $s['status']==='Active'?'success':'neutral' ?>"><?= e($s['status']) ?></span></td><td><div class="student-table-actions"><a class="button small" href="<?= e(url('students/'.$s['id'])) ?>" aria-label="View details for <?= e($s['name']) ?>">View</a><a class="text-link" href="<?= e(url('students?'.http_build_query(['edit'=>$s['id'],'q'=>$q,'class'=>$classId,'status'=>$status]))) ?>">Edit</a></div></td></tr><?php endforeach ?><?php if(!$filtered): ?><tr><td colspan="8" class="empty">No students found. Add a student, then enroll them from a batch.</td></tr><?php endif ?></tbody></table></div><div class="table-footer"><?= count($filtered) ?> of <?= count($students) ?> students</div></section>
<dialog id="student-dialog" <?= $edit || isset($_GET['new']) || !empty($_SESSION['old'])?'data-auto-open':'' ?>><div class="dialog-heading"><h2><?= $edit?'Edit':'Add' ?> student</h2><button class="icon-button" data-close aria-label="Close">×</button></div><form method="post" action="<?= e(url('save/student')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><input type="hidden" name="return_batch" value="<?= $returnBatch ?>"><div class="form-grid"><?php input('Name','name','text',$edit['name']??''); input('Phone','phone','tel',$edit['phone']??''); input('Address','address','text',$edit['address']??'',false); choose('Origin','origin',array_combine(['Facebook','TikTok','Telegram','Phone','Other'],['Facebook','TikTok','Telegram','Phone','Other']),$edit['origin']??'Other'); input('Account link or phone','account','text',$edit['account']??'',false); choose('Status','status',['Active'=>'Active','Inactive'=>'Inactive'],$edit['status']??'Active'); ?><label class="student-notes-field">Notes / description<textarea name="notes" rows="4" maxlength="5000" placeholder="Add any useful details about this student"><?= e(old('notes',$edit['notes']??'')) ?></textarea><small>Optional. Up to 5,000 characters.</small></label></div><div class="form-footer"><button type="button" class="button" data-close>Cancel</button><button class="button primary">Save student</button></div></form></dialog>
